#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#define W 2400
#define H 1800
int main(void){
    FILE*f=fopen("/app/image.ppm","rb");
    int w,h,maxv; fscanf(f,"P3\n%d %d\n%d",&w,&h,&maxv);
    unsigned char *px=malloc((size_t)w*h*3);
    for(long i=0;i<(long)w*h*3;i++){int v;fscanf(f,"%d",&v);px[i]=v;}

    FILE*fs=fopen("/app/dump_blocks.txt","w");
    for(int by=0;by<h;by+=20)for(int bx=0;bx<w;bx+=20){
        double s[3]={0,0,0},s2[3]={0,0,0};
        for(int y=by;y<by+20;y++)for(int x=bx;x<bx+20;x++){
            int p=(y*w+x)*3;
            for(int c=0;c<3;c++){s[c]+=px[p+c];s2[c]+=1.0*px[p+c]*px[p+c];}
        }
        int n=400;
        double mn=1e9,mx=-1e9;
        printf("B %d %d |",bx,by);
        for(int c=0;c<3;c++){
            double m=s[c]/n, sd=sqrt(s2[c]/n-m*m);
            printf(" %c m%.1f s%.1f", "RGB"[c], m, sd);
            if(m<mn)mn=m; if(m>mx)mx=m;
        }
        printf("\n");
    }
    fclose(fs);
    // flatness flag map: '.' flat gray, 'O' flat color, 'o' textured, '*' flat dark
    FILE*fm=fopen("/app/dump_map.txt","w");
    for(int by=0;by<h;by+=40)for(int bx=0;bx<w;bx+=40){
        double s[3]={0,0,0},s2[3]={0,0,0};
        for(int y=by;y<by+40;y++)for(int x=bx;x<bx+40;x++){
            int p=(y*w+x)*3;
            for(int c=0;c<3;c++){s[c]+=px[p+c];s2[c]+=1.0*px[p+c]*px[p+c];}
        }
        int n=1600; double m[3],sd[3]; int flat=1;
        for(int c=0;c<3;c++){m[c]=s[c]/n;sd[c]=sqrt(s2[c]/n-m[c]*m[c]); if(sd[c]>2)flat=0;}
        char ch;
        if(!flat)ch='o';
        else{
            int d=(int)(fabs(m[0]-m[1])+fabs(m[1]-m[2])+fabs(m[0]-m[2]));
            if(d>8)ch='O'; else ch= (m[0]<70?'*':(m[0]<95?'.':(m[0]<120?'+':(m[0]<145?'#':'@'))));
        }
        fputc(ch,fm);
        if((bx/40)%60==59)fputc('\n',fm);
    }
    fclose(fm);
    // row means all rows, col means all cols
    FILE*fr=fopen("/app/dump_rows.txt","w");
    for(int y=0;y<h;y++){
        double s[3]={0,0,0};
        for(int x=0;x<w;x++){int p=(y*w+x)*3;s[0]+=px[p];s[1]+=px[p+1];s[2]+=px[p+2];}
        printf("%d %.3f %.3f %.3f\n",y,s[0]/w,s[1]/w,s[2]/w);
    }
    fclose(fr);
    FILE*fc=fopen("/app/dump_cols.txt","w");
    for(int x=0;x<w;x++){
        double s[3]={0,0,0};
        for(int y=0;y<h;y++){int p=(y*w+x)*3;s[0]+=px[p];s[1]+=px[p+1];s[2]+=px[p+2];}
        printf("%d %.3f %.3f %.3f\n",x,s[0]/h,s[1]/h,s[2]/h);
    }
    fclose(fc);
    // fixed vertical lines: x in set, all y, RGB
    int xs[]={100,300,600,900,1200,1500,1800,2100,2300};
    FILE*fl=fopen("/app/dump_lines.txt","w");
    for(int i=0;i<9;i++){
        int x=xs[i];
        for(int y=0;y<h;y++){int p=(y*w+x)*3;printf("%d %d %d %d\n",y,px[p],px[p+1],px[p+2]);}
        fputc('#',fl); // separator after each of first 8 lines
        if(i<8)fseek(fl,-1,SEEK_CUR);
    }
    fclose(fl);
    // fixed horizontal lines y in set, all x, R only (G,B similar structure)
    int ys[]={100,400,700,1000,1300,1600};
    FILE*fh=fopen("/app/dump_hlines.txt","w");
    for(int i=0;i<6;i++){
        int y=ys[i];
        for(int x=0;x<w;x++){int p=(y*w+x)*3;printf("%d %d %d\n",px[p],px[p+1],px[p+2]);}
        fputc('#',fh);
    }
    fclose(fh);
    // downsampled P6: 600x450 avg of 4x4
    int DW=600,DH=450;
    FILE*fp=fopen("/app/down.p6","wb");
    fprintf(fp,"P6\n%d %d\n255\n",DW,DH);
    unsigned char out[DH][DW*3];
    for(int dy=0;dy<DH;dy++)for(int dx=0;dx<DW;dx++){
        double s[3]={0,0,0};
        for(int y=dy*4;y<dy*4+4;y++)for(int x=dx*4;x<dx*4+4;x++){
            int p=(y*w+x)*3;for(int c=0;c<3;c++)s[c]+=px[p+c];
        }
        for(int c=0;c<3;c++)out[dy][dx*3+c]=(unsigned char)(s[c]/16+0.5);
    }
    fwrite(out,1,(size_t)DH*DW*3,fp);
    fclose(fp);
